class Solution:
    def balancedString(self, s: str) -> int:
        n = len(s)
        target = n // 4
        best = n
        chars = 'QWER'
        for i in range(n):
            for j in range(i, n):
                outside = {c: 0 for c in chars}
                for p in range(n):
                    if p < i or p > j:
                        outside[s[p]] += 1
                ok = True
                for c in chars:
                    if outside[c] > target:
                        ok = False
                if ok:
                    best = min(best, j - i + 1)
        if all(s.count(c) == target for c in chars):
            return 0
        return best

