class Solution:
    def balancedString(self, s: str) -> int:
        n = len(s)
        target = n // 4
        chars = 'QWER'
        pref = [{c: 0 for c in chars}]
        for ch in s:
            cur = pref[-1].copy()
            cur[ch] += 1
            pref.append(cur)
        if all(pref[n][c] == target for c in chars):
            return 0
        best = n
        for i in range(n):
            for j in range(i, n):
                ok = True
                for c in chars:
                    inside = pref[j + 1][c] - pref[i][c]
                    if pref[n][c] - inside > target:
                        ok = False
                if ok:
                    best = min(best, j - i + 1)
        return best

