class Solution:
    def balancedString(self, s: str) -> int:
        n = len(s)
        target = n // 4
        count = {'Q': 0, 'W': 0, 'E': 0, 'R': 0}
        for ch in s:
            count[ch] += 1
        if all(count[c] == target for c in count):
            return 0
        left = 0
        ans = n
        for right, ch in enumerate(s):
            count[ch] -= 1
            while left <= right and all(count[c] <= target for c in count):
                ans = min(ans, right - left + 1)
                count[s[left]] += 1
                left += 1
        return ans

